long long floorDiv(long long a, long long b) {
    return a / b - ((a % b != 0) && ((a < 0) != (b < 0)));
}
long long ceilDiv(long long a, long long b) {
    return a / b + ((a % b != 0) && ((a < 0) == (b < 0)));
}

