#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;

long long add(long long a, long long b) { return (a + b) % MOD; }
long long sub(long long a, long long b) { return ((a - b) % MOD + MOD) % MOD; }
long long mul(long long a, long long b) { return a % MOD * (b % MOD) % MOD; }

long long power(long long a, long long e) {   // a^e mod MOD, O(log e)
    long long r = 1;
    a %= MOD;
    if (a < 0) a += MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

long long inv(long long a) { return power(a, MOD - 2); }   // a nie podzielne przez MOD
long long divide(long long a, long long b) { return mul(a, inv(b)); }

int main() {
    cout << add(MOD - 1, 5) << ' ' << sub(3, 5) << ' ' << mul(1e9, 1e9) << '\n';
    cout << power(2, 1000000) << ' ' << divide(10, 4) << '\n';   // 10/4 = 5/2 mod p
    cout << mul(divide(10, 4), 4) << '\n';                       // 10
}

const int MAXN = 1000001;
long long fact[MAXN], invFact[MAXN];

long long pw(long long a, long long e, long long m) {
    long long r = 1; a %= m;
    while (e) { if (e & 1) r = r * a % m; a = a * a % m; e >>= 1; }
    return r;
}

void initFact(int n, long long m) {
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % m;
    invFact[n] = pw(fact[n], m - 2, m);
    for (int i = n; i > 0; i--) invFact[i - 1] = invFact[i] * i % m;
}

long long C(int n, int k, long long m) {   // dwumian Newtona mod m
    if (k < 0 || k > n) return 0;
    return fact[n] * invFact[k] % m * invFact[n - k] % m;
}

